def add(j):
    n=0
    groups=[('rel',REL),('relo',RELO),('relc',RELC),('ing',ING),('dig',DIG),('sci',SCI),('sto',STO),('geo',GEO)]+list(TM.items())
    for k,arr in groups:
        for l in L: j['b'][l].setdefault(k,[])
        have={x.split('|')[1].lower() for x in j['b']['en'][k]}
        for g,d in arr:
            if d['en'].split('|')[0].lower() in have: print('sar peste',k,d['en'][:50]);continue
            for l in L: j['b'][l][k].append(f"{g}|{d[l]}")
            have.add(d['en'].split('|')[0].lower());n+=1
    return n
if __name__=='__main__':
    import json,datetime
    j=json.load(open('pack.json'));n=add(j)
    j['v']+=1;j['name']='Pachet '+str(j['v']);j['date']=datetime.date.today().isoformat()
    json.dump(j,open('pack.json','w'),ensure_ascii=False,separators=(',',':'))
    print('adăugate',n,'v',j['v'])
